"use strict";
const worldSkins={
 classic:{name:'2004 · 经典蓝',color:'#285c9a',desc:'蓝色窗口 · 旧门户'},
 olive:{name:'2001 · 银灰绿',color:'#536b3c',desc:'纸张底色 · 开机的回忆'},
 candy:{name:'2008 · 糖果粉',color:'#b55d83',desc:'空间装扮 · 青春留言'},
 amber:{name:'2005 · 橙色冲浪',color:'#d07b22',desc:'手机上网 · 温暖高光'},
 graphite:{name:'2010 · 石墨银',color:'#4a5563',desc:'金属边框 · 数码生活'},
 midnight:{name:'深夜网吧',color:'#283d53',desc:'低亮界面 · 夜读时光'}
};
let worldAppearance={skin:'classic',scanlines:false};
try{const p=JSON.parse(localStorage.getItem('archaeo-world-appearance')||'{}');if(Object.hasOwn(worldSkins,p.skin))worldAppearance.skin=p.skin;worldAppearance.scanlines=p.scanlines===true;}catch{}
function applyWorldAppearance(){document.body.dataset.worldSkin=worldAppearance.skin;document.body.classList.toggle('retro-scanlines',worldAppearance.scanlines);try{localStorage.setItem('archaeo-world-appearance',JSON.stringify(worldAppearance));}catch{}}
function worldSkinControls(){return `<div class="world-skin-grid">${Object.entries(worldSkins).map(([id,s])=>`<button data-world-skin="${id}" class="${worldAppearance.skin===id?'selected':''}" aria-pressed="${worldAppearance.skin===id}"><span style="background:${s.color}"><i></i><b>考古浏览器</b><em>新闻　音乐　小说</em></span><strong>${s.name}</strong><small>${s.desc}</small></button>`).join('')}</div>`;}
function openSkinStudio(){dialog('年代换肤工作室',`<div class="skin-studio-intro"><small>MAKE IT YOUR OWN / 换一种年代心情</small><h2>同一个过去，换一种打开方式。</h2><p>桌面和网页内容共用年代皮肤；手机里的物理外壳可以另外选择。</p></div>${worldSkinControls()}<label class="setting-row"><span>轻微屏幕纹理<small>怀旧视觉效果，可随时关闭</small></span><input type="checkbox" data-scanlines ${worldAppearance.scanlines?'checked':''}></label><div class="skin-studio-actions"><button data-action="settings">UC / Opera 等浏览器设置</button><button data-phone-lab>选择一部旧手机</button><button data-capture-view>保存当前页面</button></div>`);}
let captureLibraryPromise=null,captureObjectUrl=null;
function loadCaptureLibrary(){if(typeof html2canvas==='function')return Promise.resolve(html2canvas);if(!captureLibraryPromise)captureLibraryPromise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='vendor/html2canvas-1.4.1.min.js';s.onload=()=>typeof html2canvas==='function'?resolve(html2canvas):reject(Error('renderer unavailable'));s.onerror=()=>{captureLibraryPromise=null;reject(Error('renderer unavailable'));};document.head.appendChild(s);});return captureLibraryPromise;}
async function captureMuseum(kind='view'){
 if(phoneState.captureBusy)return;const target=kind==='phone'?$('#museum-device'):kind==='gadget'?$('#gadget-unit'):$('#content');if(!target)return toast('先打开要截图的页面');phoneState.captureBusy=true;snake.running=false;arcade.running=false;toast('正在生成本机截图…');
 try{const render=await loadCaptureLibrary();if(document.fonts?.ready)await document.fonts.ready;const isPhone=kind==='phone'||kind==='gadget',rect=target.getBoundingClientRect(),offset=isPhone?0:Math.max(0,-rect.top),height=isPhone?target.offsetHeight:Math.min(target.scrollHeight-offset,Math.max(800,Math.min(window.innerHeight,1200)));const base=await render(target,{backgroundColor:isPhone?null:'#f4f0e3',scale:2,useCORS:false,allowTaint:false,logging:false,height:Math.ceil(height),y:Math.floor(offset),ignoreElements:el=>el.tagName==='IFRAME'||el.tagName==='VIDEO'||el.hasAttribute('data-capture-ignore'),onclone:doc=>{doc.querySelectorAll('video,iframe').forEach(el=>{const note=doc.createElement('div');note.textContent='外部影像 / 历史存档 · 截图中保留占位';note.style.cssText='background:#243241;color:#d6dbdc;padding:20px;font:12px sans-serif;';el.replaceWith(note);});}});
 const pad=36,footer=92,out=document.createElement('canvas');out.width=base.width+pad*2;out.height=base.height+pad*2+footer;const ctx=out.getContext('2d');ctx.fillStyle='#eee9db';ctx.fillRect(0,0,out.width,out.height);ctx.drawImage(base,pad,pad);ctx.fillStyle='#516157';ctx.font='18px sans-serif';ctx.fillText('考古浏览器 · '+date.replaceAll('-','.')+' · 怀旧重制',pad,out.height-55);ctx.font='14px sans-serif';ctx.fillStyle='#8c9386';ctx.fillText('121.40.22.96  /  OLDDAYS MEMORY',pad,out.height-25);
 const blob=await new Promise(r=>out.toBlob(r,'image/png'));if(!blob)throw Error('png unavailable');if(captureObjectUrl)URL.revokeObjectURL(captureObjectUrl);captureObjectUrl=URL.createObjectURL(blob);const label=kind==='gadget'?retroDevices[retroDevice.model].name:isPhone?phoneModels[phoneState.model].name:current.name||'时光首页';const name=`考古浏览器-${label}-${date}.png`.replace(/[\\/:*?"<>|]/g,'_');dialog('你的年代截图',`<div class="capture-result"><img src="${captureObjectUrl}" alt="${escapeHTML(label)}的年代截图"><a class="primary" href="${captureObjectUrl}" download="${escapeHTML(name)}">保存 PNG 图片</a><p>图片在本设备生成，没有上传服务器。iPhone 可长按图片保存；跨域影片或存档可能仅显示占位。</p></div>`);toast('截图已生成，点击保存 PNG 图片');
 }catch(err){toast('这张页面暂时无法导出，请换一个本地页面或手机场景重试');}finally{phoneState.captureBusy=false;}
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-open-skins],button[data-world-skin],[data-capture-view],[data-capture-gadget]');if(!b)return;e.preventDefault();if(b.hasAttribute('data-open-skins'))return openSkinStudio();if(b.dataset.worldSkin&&Object.hasOwn(worldSkins,b.dataset.worldSkin)){worldAppearance.skin=b.dataset.worldSkin;applyWorldAppearance();openSkinStudio();toast('已换上 '+worldSkins[b.dataset.worldSkin].name);}if(b.hasAttribute('data-capture-gadget')){$('#modal').close();return captureMuseum('gadget');}if(b.hasAttribute('data-capture-view')){$('#modal').close();captureMuseum('view');}});
document.addEventListener('change',e=>{if(e.target.hasAttribute?.('data-scanlines')){worldAppearance.scanlines=e.target.checked;applyWorldAppearance();}});
